```ts
import type { FreeCamera, SceneContext } from "@babylonjs/lite";
import { attachConfigurableFreeControl } from "@babylonjs/lite";

export function attachFlyControls(
  camera: FreeCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
): () => void {
  return attachConfigurableFreeControl(camera, canvas, scene, {
    upKeys: ["Space"],
    downKeys: ["PageDown"],
    fastKeys: ["Shift"],
    fastMultiplier: 3,
  });
}
```

I wrote `src/fly-controls.ts` which delegates to the library's `attachConfigurableFreeControl`, configuring Space/PageDown as the vertical keys and Shift as the fast key with a 3× multiplier. I'm confident in the mapping of the requirements to those options; the one thing I can't verify is whether `attachConfigurableFreeControl` is re-exported from the package root versus a sub-path, since I can't inspect the actual package — if it isn't at the root you'd need to adjust the import to the appropriate sub-module path.
